    #[test]
    fn rendered_document_has_literal_sha_exact_wire_order_and_digest_binding() {
        // The owning producer plus restoration against the previous full-wire
        // SHA proves only builder usage (421597 -> 419077) and its digest move
        // after borrowing retained identities; all other wire bytes are exact.
        let graph = rendered_entry();
        let json = graph.to_json();
        let document_sha = format!(
            "sha256:{:x}",
            crate::digest_hex::LowerHex(Sha256::digest(json.as_bytes()))
        );
        // Includes the current AST carrier's charged builder bytes, so the
        // digest moves whenever the pre-bound moves: adding the static
        // implementation Vec grew Program by 24 bytes on 64-bit hosts, and the
        // split pre-bound now charges structural bytes 24 times, string
        // contents 64 times, and per-shape identity slots instead of 64
        // footprints and eight slots for every node, and an imported function
        // is now charged as the stub the projection retains instead of as a
        // second copy of the provider's contract and body, and issue #83
        // re-derived the identity copy factor from 64 to 16. Re-pinned again:
        // issue #297 (commit b8116173) added `Program.session_protocols:
        // Vec<SessionProtocolDeclaration>`, growing `Program` by another
        // `Vec`'s worth of bytes (24 on 64-bit) and moving every structural
        // charge computed from `size_of::<Program>()`. A field-by-field diff
        // of the rendered document against the pre-#297 JSON confirmed only
        // `budget.used_builder_bytes` (416669 -> 419069) and `graph_digest`
        // moved; every other field, including wire order, was byte for byte
        // identical. Re-pinned a third time in the same session: R21's own
        // Workspace Semantic Graph projection of declared session protocols
        // added `WorkspaceResolvedModule::session_protocol_facts:
        // Vec<String>` and the matching field on
        // `WorkspaceGraphProjectionModule`, each growing by one more `Vec`
        // per module for the same reason. Only `used_builder_bytes` and the
        // digest over it move; every other field of the rendered document is
        // byte for byte identical. Wire-order and independent replay below
        // remain exact. Re-pinned a fourth time, but *not* by this session's
        // own change: R21's endpoint typestate `follows` projection into the
        // Workspace Semantic Graph deliberately reuses the existing
        // `WorkspaceResolvedModule`/`WorkspaceGraphProjectionModule`
        // `session_protocol_facts: Vec<String>` field for both a declaration
        // fact and a `follows` binding fact (told apart by their own leading
        // JSON key, `{"stable_id":...` vs `{"function":...`) rather than
        // adding a second field, specifically so a follows-free corpus like
        // this fixture pays no additional `used_builder_bytes` at all --
        // confirmed by reproducing this exact new digest against an
        // unmodified checkout of this branch's own prior head (bcabfe51,
        // before any R21-follow-on change in this session), where it already
        // failed identically against the previous pin. The drift is
        // pre-existing (most likely a dependency or toolchain movement since
        // the previous pin, unrelated to session-protocol work), not
        // introduced by this change; it is re-pinned here only because this
        // session is the first to have exercised this exact test since it
        // drifted. Every other field of the rendered document remains byte
        // for byte identical; wire-order and independent replay below remain
        // exact. Re-pinned a fifth time: fixing issue #297's builder-cap
        // regression (a protocol-free real corpus was refused because every
        // `ast::Function` -- not only the ones with a `follows` clause --
        // paid `size_of::<SessionProtocolFollowsClause>()` inline) boxed
        // `Function::follows` to `Option<Box<SessionProtocolFollowsClause>>`,
        // shrinking `size_of::<Function>()` back down and moving every
        // structural charge computed from it. Only `budget.used_builder_bytes`
        // and the digest over it move; every other field of the rendered
        // document remains byte for byte identical. Re-pinned a sixth time:
        // Record Invariants v1 added the boxed
        // `TypeDeclaration::invariants: Option<Box<Vec<Expr>>>`, growing
        // `size_of::<TypeDeclaration>()` by one pointer and every structural
        // charge computed from it; only `budget.used_builder_bytes` and the
        // digest over it move.
        assert_eq!(
            document_sha,
            "sha256:9422e5da863668e10ff0841e619c99fca67b72de1b6dbbe5da3a8eaa13ded746"
        );
        assert!(json.starts_with(
                "{\"schema\":\"semaprax.workspace-semantic-graph.v1\",\"workspace_manifest_schema\":\"semaprax.workspace-semantic-manifest.v1\",\"workspace_revision\":\"sha256:workspace\",\"graph_digest\":\"sha256:"
            ));
        assert!(json.ends_with("\"]}"));
        assert_ordered_fragments(
            json,
            &[
                "\"schema\":",
                "\"workspace_manifest_schema\":",
                "\"workspace_revision\":",
                "\"graph_digest\":",
                "\"entry\":",
                "\"modules\":",
                "\"declarations\":",
                "\"edges\":",
                "\"limits\":",
                "\"budget\":",
                "\"nonclaims\":",
            ],
        );
        let types = graph
            .modules()
            .iter()
            .find(|module| module.path() == "a/types.spx")
            .unwrap();
        assert!(json.contains(&format!(
                "{{\"path\":\"a/types.spx\",\"module\":\"types.core\",\"source_graph_schema\":\"semaprax.semantic-graph.v14\",\"source_revision\":\"revision:a/types.spx\",\"source_digest\":\"{}\",\"dependency_depth\":1,\"permits\":[]}}",
                types.source_digest()
            )));
        assert!(json.contains(
                "{\"id\":\"types.point\",\"kind\":\"record\",\"identity_origin\":\"explicit\",\"owner\":null,\"path\":\"a/types.spx\",\"module\":\"types.core\"}"
            ));
        assert!(json.contains(
                "{\"caller_path\":\"m/provider.spx\",\"caller\":\"provider.api\",\"target_path\":\"a/types.spx\",\"target\":\"types.point\",\"kind\":\"type_import\",\"site\":\"module\",\"expression\":\"use.0\",\"ast_path\":\"use.0\",\"alias\":\"Point\",\"ordinal\":0}"
            ));
        assert!(json.contains(
                "\"max_managed_files\":32,\"max_reachable_modules\":32,\"max_entry_module_bytes\":16777216,\"max_total_source_bytes\":16777216"
            ));
        assert!(json.contains(
                "\"used_managed_files\":4,\"used_reachable_modules\":3,\"used_entry_module_bytes\":9,\"used_total_source_bytes\":"
            ));

        let digest_field = format!(",\"graph_digest\":\"{}\"", graph.graph_digest());
        assert_eq!(json.matches(&digest_field).count(), 1);
        let payload = json.replacen(&digest_field, "", 1);
        assert_eq!(artifact_digest(payload.as_bytes()), graph.graph_digest());
        assert_eq!(graph.budget().used_output_bytes(), json.len());
    }

    #[test]
    fn rendering_replays_input_order_and_digest_binds_payload_mutation() {
        let sources = diamond_sources();
